DROP TABLE IF EXISTS asistencia;
CREATE TABLE asistencia (
      id TEXT PRIMARY KEY,
      piso_pabellon TEXT,
      sede TEXT,
      periodo TEXT,
      dia TEXT,
      hora_inicio_prog TEXT,
      hora_final_prog TEXT,
      aula TEXT,
      nrc TEXT,
      lista_cruzada TEXT,
      codigo_docente TEXT,
      docente TEXT,
      curso TEXT,
      carrera TEXT,
      hora_inicio_real TEXT,
      hora_final_real TEXT,
      asistencia TEXT,
      puntualidad TEXT,
      observacion TEXT,
      real_horas REAL,
      ciclo TEXT,
      updated_at TEXT
    );


DROP TABLE IF EXISTS tickets;
CREATE TABLE tickets (
      id TEXT PRIMARY KEY,
      periodo TEXT,
      fecha TEXT,
      dia TEXT,
      hora_reporte TEXT,
      rango TEXT,
      ambiente TEXT,
      piso TEXT,
      pabellon TEXT,
      tipo_solicitud TEXT,
      estado TEXT,
      descripcion_solucion TEXT,
      responsable TEXT,
      created_at TEXT,
      updated_at TEXT
    );


DROP TABLE IF EXISTS hojas_manuales;
CREATE TABLE hojas_manuales (
      id TEXT PRIMARY KEY,
      periodo TEXT,
      codigo TEXT UNIQUE,
      fecha TEXT,
      nrc TEXT,
      docente TEXT,
      curso TEXT,
      carrera TEXT,
      motivo TEXT,
      asistente TEXT,
      created_at TEXT
    );


DROP TABLE IF EXISTS reservas;
CREATE TABLE reservas (
      id TEXT PRIMARY KEY,
      fecha TEXT,
      mes TEXT,
      dia TEXT,
      inicio TEXT,
      final TEXT,
      aula TEXT,
      ubicacion TEXT,
      docente TEXT,
      detalle TEXT,
      usuario TEXT,
      prioridad TEXT,
      created_at TEXT
    );

